from east_py_datascience import alns_optimize

@East.function([FloatType, FloatType], BooleanType, cse=False)
def alnsOptimizeWithAcceptance(b, start_temp, end_temp):
    initial = b.let(
        {'leg_distances': [6.0, 9.0, 4.0, 11.0, 7.0], 'total_distance': 37.0},
        StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)]),
    )
    objective = b.const(
        East.function(
            [StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)])],
            FloatType,
            lambda b, plan: plan.total_distance,
        ),
    )
    @East.function(
        [StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)])],
        StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)]),
    )
    def _f1(b, plan):
        longest = b.let(
            plan.leg_distances.reduce(
                lambda b, best, d, _8: East.if_else((d > best), d, best),
                0.0,
            ),
        )
        after = b.let(
            plan.leg_distances.map(
                lambda b, d, _11: East.if_else((East.Float.abs((d - longest)) < 0.001), 0.0, d),
            ),
        )
        b.return_({'leg_distances': after, 'total_distance': plan.total_distance})
    remove_longest = b.const(_f1)
    @East.function(
        [StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)])],
        StructType([('leg_distances', ArrayType(FloatType)), ('total_distance', FloatType)]),
    )
    def _f2(b, plan):
        repaired = b.let(plan.leg_distances.map(lambda b, d, _16: East.if_else((d < 0.01), 3.0, d)))
        new_total = b.let(repaired.reduce(lambda b, acc, d, _20: (acc + d), 0.0))
        b.return_({'leg_distances': repaired, 'total_distance': new_total})
    reinsert = b.const(_f2)
    config = b.let(
        {
            'stop': some(variant('max_iterations', 30)),
            'acceptance': some(
                variant(
                    'simulated_annealing',
                    {
                        'start_temperature': some(start_temp),
                        'end_temperature': some(end_temp),
                        'step': some(0.95),
                    },
                ),
            ),
            'operator_selection': none,
            'seed': some(42),
        },
        StructType([
            ('stop', OptionType(VariantType([
                ('max_iterations', IntegerType),
                ('max_runtime', FloatType),
                ('no_improvement', IntegerType),
            ]))),
            ('acceptance', OptionType(VariantType([
                ('hill_climbing', NullType),
                ('record_to_record', StructType([('threshold', OptionType(FloatType))])),
                ('simulated_annealing', StructType([
                    ('start_temperature', OptionType(FloatType)),
                    ('end_temperature', OptionType(FloatType)),
                    ('step', OptionType(FloatType)),
                ])),
