    )
    @East.function([FloatType, VectorType(FloatType), VectorType(FloatType)], FloatType)
    def _f1(b, t, params, _fixed):
        amplitude = b.let(params.get(0))
        decay_rate = b.let(params.get(1))
        baseline = b.let(params.get(2))
        b.return_((amplitude * East.Float.exp((-decay_rate * t)) + baseline))
    degradation_model = b.const(_f1)
    config = b.let(
        {
            'max_iter': variant('some', 5000),
            'initial_guess': variant(
                'some',
                East.new_array(FloatType, [50.0, 0.3, 10.0]).to_vector(),
            ),
        },
        StructType([
            ('max_iter', VariantType([('some', IntegerType)])),
            ('initial_guess', VariantType([('some', VectorType(FloatType))])),
        ]),
    )
    result = b.let(
        scipy_curve_fit(
            variant(
                'custom',
                {
