import { East, some, none, BooleanType, IntegerType, FloatType, ArrayType, StructType, OptionType, VectorType } from "@elaraai/east";
import { SimAnneal } from "@elaraai/east-py-datascience";

export const simannealOptimizePermutation = East.function([], BooleanType, ($) => {
  const processing_times = $.let(
    East.Vector.fromArray(East.value([10, 5, 20, 3], ArrayType(FloatType))),
  );
  const due_dates = $.let(East.Vector.fromArray(East.value([15, 10, 40, 8], ArrayType(FloatType))));
  const weights = $.let(East.Vector.fromArray(East.value([1, 8, 2, 10], ArrayType(FloatType))));
  const energy = $.const(
    East.function([VectorType(IntegerType)], FloatType, ($, sequence) => {
      const current_time = $.let(0);
      const total_tardiness = $.let(0);
      $.for(East.Array.range(East.value(0n), 4n, 1n), ($, i, _7, label) => {
        const job = $.let(sequence.get(i));
        $.assign(current_time, current_time.add(processing_times.get(job)));
        const tardiness = $.let(current_time.subtract(due_dates.get(job)));
        const clamped = $.let(East.greater(tardiness, 0).ifElse(($) => tardiness, ($) => 0));
        $.assign(total_tardiness, total_tardiness.add(weights.get(job).multiply(clamped)));
      });
      $.return(total_tardiness);
    }),
  );
  const initial = $.let(
    East.Vector.fromArray(East.value([0n, 1n, 2n, 3n], ArrayType(IntegerType))),
  );
  const config = $.let(
    {
      t_max: some(1000),
      t_min: some(0.1),
      steps: some(5000n),
      updates: none,
      auto_schedule: none,
      random_state: some(42n),
