export const simannealOptimizeSubset = East.function([FloatType], BooleanType, ($, budget) => {
  const task_costs = $.let(
    East.Vector.fromArray(East.value([5, 12, 3, 8, 15, 7], ArrayType(FloatType))),
  );
  const task_benefits = $.let(
    East.Vector.fromArray(East.value([4, 10, 2, 7, 13, 6], ArrayType(FloatType))),
  );
  const energy = $.const(
    East.function([VectorType(BooleanType)], FloatType, ($, selection) => {
