        ],
        ArrayType(ArrayType(FloatType)),
      ),
    ),
  );
  const y_train = $.let(
    East.Vector.fromArray(
      East.value([0n, 0n, 0n, 0n, 0n, 0n, 0n, 0n, 1n, 1n], ArrayType(IntegerType)),
    ),
  );
  const config = $.let(
    {
      n_estimators: variant("some", 50n),
      max_depth: variant("some", 3n),
      learning_rate: variant("some", 0.3),
      min_child_weight: variant("none", null),
      subsample: variant("none", null),
      colsample_bytree: variant("none", null),
      reg_alpha: variant("none", null),
      reg_lambda: variant("none", null),
      gamma: variant("none", null),
      random_state: variant("some", 42n),
      n_jobs: variant("none", null),
      sample_weight: variant("none", null),
      categorical_features: variant("none", null),
      categorical_n: variant("none", null),
      max_cat_to_onehot: variant("none", null),
      max_cat_threshold: variant("none", null),
      scale_pos_weight: variant("some", 4),
    },
    StructType({
      n_estimators: VariantType({ some: IntegerType }),
      max_depth: VariantType({ some: IntegerType }),
      learning_rate: VariantType({ some: FloatType }),
      min_child_weight: VariantType({ none: NullType }),
      subsample: VariantType({ none: NullType }),
      colsample_bytree: VariantType({ none: NullType }),
      reg_alpha: VariantType({ none: NullType }),
      reg_lambda: VariantType({ none: NullType }),
      gamma: VariantType({ none: NullType }),
      random_state: VariantType({ some: IntegerType }),
      n_jobs: VariantType({ none: NullType }),
      sample_weight: VariantType({ none: NullType }),
      categorical_features: VariantType({ none: NullType }),
      categorical_n: VariantType({ none: NullType }),
      max_cat_to_onehot: VariantType({ none: NullType }),
      max_cat_threshold: VariantType({ none: NullType }),
      scale_pos_weight: VariantType({ some: FloatType }),
    }),
  );
  const model = $.let(XGBoost.trainClassifier(X_train, y_train, config));
  const X_new = $.let(
    East.Matrix.fromArray(East.value([[0.5, 0.5], [10.3, 10.2]], ArrayType(ArrayType(FloatType)))),
  );
  const classes = $.let(XGBoost.predictClass(model, X_new));
  return East.equal(classes.get(0n), 0n).ifElse(
    ($) => East.equal(classes.get(1n), 1n),
    ($) => false,
  );
});

