// Attached Prev/Next pair — two buttons sharing a border
// inputs: []
East.function([], UIComponentType, (_$) => {
        return (
            <ButtonGroup attached>
                <Button variant="outline" size="md">Prev</Button>
                <Button variant="outline" size="md">Next</Button>
            </ButtonGroup>
        );
    })

// ButtonGroup configurator — a composition preset axis (timescale / split) plus an attached switch
// inputs: []
East.function([], UIComponentType, (_$) => (
        <Reactive>{$ => {
            const presets = $.const(["timescale", "split"], ArrayType(StringType));

            const presetBind = $.let(State.bind([StringType], "buttongroup_preset", "timescale"));
            const attachedBind = $.let(State.bind([BooleanType], "buttongroup_attached", true));

            const pKey = $.let(presetBind.read());
            const attachedOn = $.let(attachedBind.read());

            const onPreset = $.const(East.function([StringType], NullType, ($, next) => { $(presetBind.write(next)); }));
            const onAttached = $.const(East.function([BooleanType], NullType, ($, next) => { $(attachedBind.write(next)); }));

            // children are VALUES — the preset swaps the kid array on the
            // ONE group; attached stays live.
            const splitKids = $.let([
                <Button variant="solid" colorPalette="brand" size="md">Deploy</Button>,
                <IconButton prefix="fas" name="chevron-down" label="More deploy options" variant="solid" colorPalette="brand" size="md" />,
            ], ArrayType(UIComponentType));
            const rangeKids = $.let([
                <Button variant="outline" size="sm">1d</Button>,
                <Button variant="outline" size="sm">1w</Button>,
                <Button variant="outline" size="sm">1m</Button>,
                <Button variant="outline" size="sm">3m</Button>,
                <Button variant="outline" size="sm">1y</Button>,
            ], ArrayType(UIComponentType));
            const kids = $.let(pKey.equal("split").ifElse(_$ => splitKids, _$ => rangeKids));
            const preview = $.const(<ButtonGroup attached={attachedOn}>{kids}</ButtonGroup>);

            return (
                <Configurator
                    controls={[
                        Configurator.Control("Preset", pKey,
                            <SegmentGroup value={pKey} onChange={onPreset} size="sm"
                                items={presets.map((_$, p) => SegmentGroup.Item(p, <Text>{p.upperCase()}</Text>))} />),
                        Configurator.Slot("Layout",
                            <HStack gap="5" align="center" wrap="wrap">
                                <Switch checked={attachedOn} label="Attached" onChange={onAttached} />
                            </HStack>),
                    ]}
                    preview={preview}
                    spec={[
                        Configurator.Spec("Buttons", pKey.equal("split").ifElse(_$ => "2 · mixed", _$ => "5")),
                    ]}
                />
            );
        }}</Reactive>
    ))

// Create a simple button with a text label
// inputs: []
East.function([], UIComponentType, (_$) => {
        return <Button>Click me</Button>;
    })

// Button configurator — variant, palette, size and colour axes plus loading, icons and rich-label switches driving one live button; the aside increments a reactive count
// inputs: []
East.function([], UIComponentType, (_$) => {
        return (
            <Reactive>{$ => {
                // Enumerated axes are just their variants — `getTag()` gives the
                // segment key AND its label, so there is no parallel table to
                // keep in step.
                const variants = $.const([
                    variant("solid", null), variant("outline", null),
                    variant("ghost", null), variant("plain", null),
                ], ArrayType(Button.Types.Variant));

                const palettes = $.const([
                    variant("brand", null), variant("success", null), variant("warning", null),
                    variant("danger", null), variant("info", null), variant("gray", null),
                ], ArrayType(Style.Types.ColorScheme));

                const sizes = $.const([
                    variant("xs", null), variant("sm", null), variant("md", null), variant("lg", null),
                ], ArrayType(Style.Types.Size));

                const variantBind = $.let(State.bind([StringType], "button_variant", "solid"));
                const paletteBind = $.let(State.bind([StringType], "button_palette", "brand"));
                const sizeBind    = $.let(State.bind([StringType], "button_size", "md"));
                const loadingBind = $.let(State.bind([BooleanType], "button_loading", false));
                const richBind    = $.let(State.bind([BooleanType], "button_rich", false));
                const counter     = $.let(State.bind([IntegerType], "button_counter", 0n));

                const vKey    = $.let(variantBind.read());
                const pKey    = $.let(paletteBind.read());
                const sKey    = $.let(sizeBind.read());
                const loading = $.let(loadingBind.read());
                const rich    = $.let(richBind.read());
                const count   = $.let(counter.read());

                const onVariant = $.const(East.function([StringType], NullType, ($, next) => { $(variantBind.write(next)); }));
                const onPalette = $.const(East.function([StringType], NullType, ($, next) => { $(paletteBind.write(next)); }));
                const onSize    = $.const(East.function([StringType], NullType, ($, next) => { $(sizeBind.write(next)); }));
                const onLoading = $.const(East.function([BooleanType], NullType, ($, next) => { $(loadingBind.write(next)); }));
                const onRich    = $.const(East.function([BooleanType], NullType, ($, next) => { $(richBind.write(next)); }));
                const inc       = $.const(East.function([], NullType, $ => {
                    const cur = $.let(counter.read());
                    $(counter.write(cur.add(1n)));
                }));

                // Each selection is a lookup into the same array the control renders.
                const buttonVariant = $.let(variants.filter((_$, v) => v.getTag().equal(vKey)).get(0n));
                const palette = $.let(palettes.filter((_$, v) => v.getTag().equal(pKey)).get(0n));
                const size = $.let(sizes.filter((_$, v) => v.getTag().equal(sKey)).get(0n));

                // The label is a UIComponentType slot — the rich switch swaps the
                // plain run for an HStack of Texts (primary + muted caption).
                const btnLabel = $.const(rich.ifElse(
                    _$ => (
                        <HStack gap="1" align="center">
                            <Text>Accept</Text>
                            <Text color="fg.inverse">→ log to MES</Text>
                        </HStack>
                    ),
                    _$ => <Text>Save Changes</Text>,
                ));

                // ONE button — the icon slots compose on permanently; the raw
                // colour escape hatches live in their own example.
                const btn = $.const(
                    <Button variant={buttonVariant} colorPalette={palette} size={size}
                        loading={loading} loadingText="Submitting…" loadingIcon={{ prefix: "fas", name: "spinner" }}
                        startIcon={{ prefix: "fas", name: "save" }} endIcon={{ prefix: "fas", name: "arrow-right" }}>
                        {btnLabel}
                    </Button>,
                );

                return (
                    <Configurator
                        controls={[
                            Configurator.Control("Variant", vKey,
                                <Select value={vKey} onChange={onVariant} size="sm"
                                    items={variants.map((_$, v) => Select.Item(v.getTag(), v.getTag()))} />),
                            Configurator.Control("Palette", pKey,
                                <Select value={pKey} onChange={onPalette} size="sm"
                                    items={palettes.map((_$, v) => Select.Item(v.getTag(), v.getTag()))} />),
                            Configurator.Control("Size", sKey,
                                <Select value={sKey} onChange={onSize} size="sm"
                                    items={sizes.map((_$, v) => Select.Item(v.getTag(), v.getTag()))} />),
                            // Slots, not Controls: the switches report as the
                            // Loading / Icons / Label spec rows below rather than
                            // as one value each.
                            Configurator.Slot("State",
                                <HStack gap="5" align="center" wrap="wrap">
                                    <Switch checked={loading} label="Loading" onChange={onLoading} />
                                </HStack>),
                            Configurator.Slot("Content",
                                <HStack gap="5" align="center" wrap="wrap">
                                    <Switch checked={rich} label="Rich label" onChange={onRich} />
                                </HStack>),
                        ]}
                        preview={btn}
                        aside={{
                            label: "Count · Reactive",
                            body: (
                                <HStack gap="3" align="center">
                                    <Text>{East.str`Clicked ${East.print(count)} times`}</Text>
                                    <Button size="xs" onClick={inc}>Click me</Button>
                                </HStack>
                            ),
                        }}
                        spec={[
                            Configurator.Spec("Loading", loading.ifElse(_$ => "Submitting… · spinner", _$ => "idle")),
                            Configurator.Spec("Label", rich.ifElse(_$ => "HStack · Accept + caption", _$ => "Save Changes")),
                            Configurator.Spec("Slots", "variant recipe"),
                        ]}
                    />
                );
            }}</Reactive>
        );
    })

// Colour escape hatches — link and branded-ink buttons beside the recipe default
// inputs: []
East.function([], UIComponentType, (_$) => (
        <HStack gap="3" align="center">
            <Button variant="solid" colorPalette="brand">Recipe</Button>
            <Button variant="ghost" color="link" background="transparent" borderColor="transparent" hoverBackground="bg.brand.subtle">Link</Button>
            <Button variant="solid" color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse">Branded</Button>
        </HStack>
    ))

// Default CloseButton — aria-label renders as 'Close'
// inputs: []
East.function([], UIComponentType, (_$) => {
        return <CloseButton />;
    })

// CloseButton configurator — variant, size and colour axes on one live button with a custom aria-label; the aside counts dismissals
// inputs: []
East.function([], UIComponentType, (_$) => (
        <Reactive>{$ => {
            const variants = $.const([
                variant("ghost", null), variant("subtle", null), variant("solid", null),
            ], ArrayType(CloseButton.Types.Variant));
            const sizes = $.const([
                variant("sm", null), variant("md", null), variant("lg", null),
            ], ArrayType(Style.Types.Size));

            const variantBind = $.let(State.bind([StringType], "closebutton_variant", "ghost"));
            const sizeBind = $.let(State.bind([StringType], "closebutton_size", "md"));
            const countBind = $.let(State.bind([IntegerType], "closebutton_count", 0n));

            const vKey = $.let(variantBind.read());
            const sKey = $.let(sizeBind.read());
            const count = $.let(countBind.read());

            const onVariant = $.const(East.function([StringType], NullType, ($, next) => { $(variantBind.write(next)); }));
            const onSize = $.const(East.function([StringType], NullType, ($, next) => { $(sizeBind.write(next)); }));
            const dismiss = $.const(East.function([], NullType, $ => {
                const cur = $.let(countBind.read());
                $(countBind.write(cur.add(1n)));
            }));

            const buttonVariant = $.let(variants.filter((_$, v) => v.getTag().equal(vKey)).get(0n));
            const size = $.let(sizes.filter((_$, v) => v.getTag().equal(sKey)).get(0n));

            // ONE button — recipe colouring; the escape hatches live in
            // their own example.
            const preview = $.const(
                <CloseButton label="Dismiss banner" variant={buttonVariant} size={size} onClick={dismiss} />,
            );

            return (
                <Configurator
                    controls={[
                        Configurator.Control("Variant", vKey,
                            <SegmentGroup value={vKey} onChange={onVariant} size="sm"
                                items={variants.map((_$, v) => SegmentGroup.Item(v.getTag(), <Text>{v.getTag().upperCase()}</Text>))} />),
                        Configurator.Control("Size", sKey,
                            <SegmentGroup value={sKey} onChange={onSize} size="sm"
                                items={sizes.map((_$, v) => SegmentGroup.Item(v.getTag(), <Text>{v.getTag().upperCase()}</Text>))} />),
                    ]}
                    preview={preview}
                    aside={{
                        label: "Dismissals · Reactive",
                        body: <Text.MonoLabel>{East.str`DISMISSED · ${East.print(count)}`}</Text.MonoLabel>,
                    }}
                    spec={[
                        Configurator.Spec("aria-label", "Dismiss banner"),
                    ]}
                />
            );
        }}</Reactive>
    ))

// Colour overrides — inverse-ink close button via the raw escape hatches
// inputs: []
East.function([], UIComponentType, (_$) => (
        <CloseButton label="Dismiss banner" variant="solid" color="fg.inverse" background="bg.inverse" hoverBackground="bg.inverse" />
    ))

// Icon-only copy affordance (aria-label 'Copy to clipboard')
// inputs: []
East.function([], UIComponentType, (_$) => {
        return <CopyButton>super-secret-api-key</CopyButton>;
    })

// CopyButton configurator — variant and colour axes on one live labelled copy button with a custom Copied! timeout
// inputs: []
East.function([], UIComponentType, (_$) => (
        <Reactive>{$ => {
            const variants = $.const([
                variant("ghost", null), variant("outline", null), variant("solid", null),
            ], ArrayType(CopyButton.Types.Variant));

            const variantBind = $.let(State.bind([StringType], "copybutton_variant", "outline"));

            const vKey = $.let(variantBind.read());

            const onVariant = $.const(East.function([StringType], NullType, ($, next) => { $(variantBind.write(next)); }));

            const buttonVariant = $.let(variants.filter((_$, v) => v.getTag().equal(vKey)).get(0n));

            // ONE button — recipe colouring; the escape hatches live in
            // their own example.
            const preview = $.const(
                <CopyButton label="Copy API key" variant={buttonVariant} timeout="1500">
                    elaraai_sk_live_xxxxxxxx
                </CopyButton>,
            );

            return (
                <Configurator
                    controls={[
                        Configurator.Control("Variant", vKey,
                            <SegmentGroup value={vKey} onChange={onVariant} size="sm"
                                items={variants.map((_$, v) => SegmentGroup.Item(v.getTag(), <Text>{v.getTag().upperCase()}</Text>))} />),
                    ]}
                    preview={preview}
                    spec={[
                        Configurator.Spec("Timeout", "1500ms"),
                    ]}
                />
            );
        }}</Reactive>
    ))

// Colour overrides — inverse-ink copy button with a success tint
// inputs: []
East.function([], UIComponentType, (_$) => (
        <CopyButton label="Copy API key" variant="solid" color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse" successColor="fg.success">
            elaraai_sk_live_xxxxxxxx
        </CopyButton>
    ))

// Icon-only close affordance with required aria-label
// inputs: []
East.function([], UIComponentType, (_$) => {
        return <IconButton prefix="fas" name="xmark" label="Close" variant="ghost" />;
    })

// IconButton configurator — glyph, size, palette, colour, badge and attention axes plus a loading switch driving one live icon button; the aside folds the reactive click counter
// inputs: []
East.function([], UIComponentType, (_$) => {
        return (
            <Reactive>{$ => {
                // Enumerated axes are just their variants — `getTag()` gives the
                // segment key AND its label, so there is no parallel table to
                // keep in step.
                const sizes = $.const([
                    variant("xs", null), variant("sm", null), variant("md", null), variant("lg", null),
                ], ArrayType(Style.Types.Size));

                const palettes = $.const([
                    variant("brand", null), variant("success", null), variant("warning", null),
                    variant("danger", null), variant("info", null), variant("gray", null),
                ], ArrayType(Style.Types.ColorScheme));

                const attentions = $.const([
                    none, variant("pulse", null), variant("ring", null),
                ], ArrayType(IconButton.Types.Attention));

                // The badge forms need a struct — a badge is its superscript text
                // PLUS the bubble palette that reads with it (`""` renders the
                // dot-only indicator), so there is no single value to name it by.
                const badges = $.const([
                    { label: "count", text: "3",   palette: variant("danger", null) },
                    { label: "99+",   text: "99+", palette: variant("warning", null) },
                    { label: "dot",   text: "",    palette: variant("danger", null) },
                ], ArrayType(StructType({ label: StringType, text: StringType, palette: Style.Types.ColorScheme })));

                const glyphBind     = $.let(State.bind([StringType], "icon_button_glyph", "bell"));
                const sizeBind      = $.let(State.bind([StringType], "icon_button_size", "md"));
                const paletteBind   = $.let(State.bind([StringType], "icon_button_palette", "brand"));
                const colourBind    = $.let(State.bind([StringType], "icon_button_color", "palette"));
                const badgeBind     = $.let(State.bind([StringType], "icon_button_badge", "count"));
                const attentionBind = $.let(State.bind([StringType], "icon_button_attention", "none"));
                const loadingBind   = $.let(State.bind([BooleanType], "icon_button_loading", false));
                const counter       = $.let(State.bind([IntegerType], "icon_button_counter", 0n));

                const gKey    = $.let(glyphBind.read());
                const sKey    = $.let(sizeBind.read());
                const pKey    = $.let(paletteBind.read());
                const cKey    = $.let(colourBind.read());
                const bKey    = $.let(badgeBind.read());
                const aKey    = $.let(attentionBind.read());
                const loading = $.let(loadingBind.read());
                const count   = $.let(counter.read());

                const onGlyph     = $.const(East.function([StringType], NullType, ($, next) => { $(glyphBind.write(next)); }));
                const onSize      = $.const(East.function([StringType], NullType, ($, next) => { $(sizeBind.write(next)); }));
                const onPalette   = $.const(East.function([StringType], NullType, ($, next) => { $(paletteBind.write(next)); }));
                const onColour    = $.const(East.function([StringType], NullType, ($, next) => { $(colourBind.write(next)); }));
                const onBadge     = $.const(East.function([StringType], NullType, ($, next) => { $(badgeBind.write(next)); }));
                const onAttention = $.const(East.function([StringType], NullType, ($, next) => { $(attentionBind.write(next)); }));
                const onLoading   = $.const(East.function([BooleanType], NullType, ($, next) => { $(loadingBind.write(next)); }));
                const inc         = $.const(East.function([], NullType, $ => {
                    const cur = $.let(counter.read());
                    $(counter.write(cur.add(1n)));
                }));

                // Each selection is a lookup into the same array the control renders.
                const size = $.let(sizes.filter((_$, v) => v.getTag().equal(sKey)).get(0n));
                const palette = $.let(palettes.filter((_$, v) => v.getTag().equal(pKey)).get(0n));
                const attention = $.let(attentions.filter((_$, v) => v.getTag().equal(aKey)).get(0n));
                const bdg = $.let(badges.filter((_$, o) => o.label.equal(bKey)).get(0n));

                // The glyph axis carries its own rendered value: a Font Awesome
                // identity is a COMPILE-TIME pair — `prefix` / `name` / `label`
                // take host literals, never expressions — so each row holds the
                // built button beside the identity it renders. And because the
                // colour slots are escape hatches the factory omits from the IR
                // entirely when absent, each row holds the palette-recipe build
                // AND the branded build: `palette` is the absence of the props,
                // not an empty value of them, and the preview picks between the
                // two. Every button takes the live style axes.
                const glyphs = $.const([
                    {
                        label: "bell", prefix: "fas", name: "bell", aria: "Alerts",
                        button: <IconButton prefix="fas" name="bell" label="Alerts" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} />,
                        branded: <IconButton prefix="fas" name="bell" label="Alerts" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse" />,
                    },
                    {
                        label: "rotate", prefix: "fas", name: "rotate", aria: "Refresh",
                        button: <IconButton prefix="fas" name="rotate" label="Refresh" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} />,
                        branded: <IconButton prefix="fas" name="rotate" label="Refresh" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse" />,
                    },
                    {
                        label: "rocket", prefix: "fas", name: "rocket", aria: "Deploy",
                        button: <IconButton prefix="fas" name="rocket" label="Deploy" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} />,
                        branded: <IconButton prefix="fas" name="rocket" label="Deploy" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse" />,
                    },
                    {
                        label: "inbox", prefix: "fas", name: "inbox", aria: "Unread",
                        button: <IconButton prefix="fas" name="inbox" label="Unread" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} />,
                        branded: <IconButton prefix="fas" name="inbox" label="Unread" size={size} colorPalette={palette} badge={bdg.text} badgeColorPalette={bdg.palette} attention={attention} loading={loading} loadingIcon={{ prefix: "fas", name: "spinner" }} color="fg.inverse" background="bg.inverse" borderColor="border.brand" hoverBackground="bg.inverse" />,
                    },
                ], ArrayType(StructType({ label: StringType, prefix: StringType, name: StringType, aria: StringType, button: UIComponentType, branded: UIComponentType })));

                const glyph = $.let(glyphs.filter((_$, g) => g.label.equal(gKey)).get(0n));
                const btn = $.const(cKey.equal("palette").ifElse(_$ => glyph.button, _$ => glyph.branded));

                // The colour axis is two-valued — palette recipe or the branded
                // slot set — so a bare array of the two keys is the whole table.
                const colours = $.const(["palette", "branded"], ArrayType(StringType));

                return (
                    <Configurator
                        controls={[
                            Configurator.Control("Glyph", gKey,
                                <Select value={gKey} onChange={onGlyph} size="sm"
                                    items={glyphs.map((_$, g) => Select.Item(g.label, g.label))} />),
                            Configurator.Control("Size", sKey,
                                <Select value={sKey} onChange={onSize} size="sm"
                                    items={sizes.map((_$, v) => Select.Item(v.getTag(), v.getTag()))} />),
                            Configurator.Control("Palette", pKey,
                                <Select value={pKey} onChange={onPalette} size="sm"
                                    items={palettes.map((_$, v) => Select.Item(v.getTag(), v.getTag()))} />),
