                return event.match({
                    add: (_$, add) => East.equal(add.from.key, "kim").and(_$ => weekend(add.into.slot)).not(),
                    move: (_$, mv) => weekend(mv.to.slot).not(),
                    remove: (_$) => East.value(true),
                    resize: (_$) => East.value(true),
