                        ]}
                        item={r => ({ key: r.id, x: r.x, y: r.y, label: r.id, icon: "industry" })}
                        links={[{ id: "l1", a: "PACK-A", b: "SHIP" }]}
                        link={l => ({ key: l.id, from: l.a, to: l.b })}
                        linkMode={lm}
                        readOnlyLinks={roLinks}
                        onCreateLink={onCreateLink}
                        onEditLink={onEditLink}
