            const weeklyCells = $.const(East.function([DateTimeType, ArrayType(FloatType)], ArrayType(Plan.Types.HeatCell), ($, from, weekly) =>
                East.Array.generate(weekly.size(), Plan.Types.HeatCell, (_$, i) => ({
