                            label: r => r.label,
                            cells: r => Plan.heatCells(loadCells(r.load), { min: 0, max: 100 }),
                        }),
                    ]),
                }),
            ], ArrayType(Plan.Types.Series(HallGroup)));
            const axis = $.const(Plan.axis({ window: { min: week(27n), max: week(39n) }, resolution: "week", now: week(31n) }));
            return (
                <Plan.View
                    axis={axis}
                    data={halls}
                    series={series}
                />
            );
        }}</Reactive>
    ))

