                                const label = $.let(s.state.match({
                                    proposed: (_$, p) => p.hasTag("removed").ifElse(
                                        () => East.str`${hrs}h`,
                                        () => East.str`+${hrs}h`),
                                }, _$ => East.str`${hrs}h`), StringType);
                                return Plan.chip({ key: s.key, from: s.from, to: s.to, label, state: s.state });
