                        Plan.mark({ key: "rel", at: week(33n), kind: "milestone", label: "REL 2.4" }),
                    ] })]),
            ], ArrayType(Plan.Types.Series(Block)));
            const axis = $.const(Plan.axis({ window: { min: week(27n), max: week(39n) }, resolution: "week", now: week(31n) }));
            return (
                <Plan.View
                    axis={axis}
                    data={blocks}
                    series={series}
