    {
        name: "Units by SKU",
        jq: `.orders
| [.[] | . as $order | .lines[] | . + {order_id: $order.id}]
| group_by(.sku)
| map({sku: .[0].sku, units: map(.qty) | add, orders: map(.order_id) | unique | length})
