// Print a link as the planner types it — from > to, members comma-separated, a range as from-to, a count as N x key and the placeholder as TBC
// inputs: []  returns: "R2140, R2141-R2145 > 4 x CNC router, TBC"
East.function([], StringType, ($) => {
        const link = $.const({
            from: [variant("identified", { key: "R2140" }), variant("range", { from: "R2141", to: "R2145" })],
            to:   [variant("counted", { n: 4n, key: "CNC router" }), variant("placeholder", null)],
        }, Sheet.Types.Link);
        return Sheet.link.print(link);
    })

// Parse the planner's text into a typed link against a register — codes and aliases resolve case-insensitively, N x kind counts a family, a short range completes from its lower bound, TBC is the placeholder and anything else is kept as text
// inputs: []  returns: {
        from: [variant("identified", { key: "R2140" })],
        to: [variant("counted", { n: 4n, key: "CNC router" }), variant("range", { from: "R2141", to: "R2145" }), variant("placeholder", null), variant("text", "spray shop")],
    }
East.function([], Sheet.Types.Link, ($) => {
        const members = $.const([
            { key: "R2140", label: "R2140", kind: "machine", aliases: [], meta: some("CNC router"), parent: some("Bay 2"), tone: none },
            { key: "CNC router", label: "CNC router", kind: "family", aliases: ["router", "routers"], meta: some("family"), parent: none, tone: none },
        ], Sheet.Types.RegisterMembers);
        return Sheet.link.parse("r2140 > 4 x router, R2141-45, TBC, spray shop", members);
    })

// Apply an entry patch against the complete inline snapshot
// inputs: []  returns: [{ id: "a", task: "Cut", qty: 3n }]
const Job = StructType({ id: StringType, task: StringType, qty: IntegerType });

East.function([], ArrayType(Job), ($) => {
        const before = $.const({ id: "a", task: "Cut", qty: 2n }, Job);
        const after = $.const({ id: "a", task: "Cut", qty: 3n }, Job);
        const rows = $.const([before], ArrayType(Job));
        const oldEntry = $.const(some(before), OptionType(Job));
        const newEntry = $.const(some(after), OptionType(Job));
        const batch = $.const({
            requestId: "example-request", base: variant("snapshot", rows), label: "Set quantity",
            changes: [{ id: "a", patch: East.diff(oldEntry, newEntry), place: none }],
        }, Sheet.Types.ChangeSet(Job));
        const apply = $.const(Sheet.apply(Job, "id"));
        return apply(rows, batch, none).unwrap("applied");
    })

// Apply a batch to work packages and loose tasks in one collection — Sheet.Types.Entry names the group-or-row union by its child field, and one entry patch reorders a package's tasks
// inputs: []  returns: ["C-18 nesting: Inspect batches → Cut panels", "Pack for delivery"]
East.function([], ArrayType(StringType), ($) => {
        const TaskType = StructType({ id: StringType, task: StringType });
        const PackageType = StructType({ id: StringType, name: StringType, tasks: ArrayType(TaskType) });
        const Entry = Sheet.Types.Entry(PackageType, "tasks");
        const before = $.const(variant("group", { id: "p1", name: "C-18 nesting", tasks: [
            { id: "t1", task: "Cut panels" }, { id: "t2", task: "Inspect batches" },
        ] }), Entry);
        const after = $.const(variant("group", { id: "p1", name: "C-18 nesting", tasks: [
            { id: "t2", task: "Inspect batches" }, { id: "t1", task: "Cut panels" },
        ] }), Entry);
        const loose = $.const(variant("row", { id: "t9", task: "Pack for delivery" }), Entry);
        const entries = $.const([before, loose], ArrayType(Entry));
        const oldEntry = $.const(some(before), OptionType(Entry));
        const newEntry = $.const(some(after), OptionType(Entry));
        const batch = $.const({
            requestId: "reorder-nesting", base: variant("snapshot", entries), label: "Move a task",
            changes: [{ id: "p1", patch: East.diff(oldEntry, newEntry), place: none }],
        }, Sheet.Types.ChangeSet(Entry));
        const apply = $.const(Sheet.apply(Entry, "id"));
        const applied = $.const(apply(entries, batch, none).unwrap("applied"));
        return applied.map((_$, entry) => entry.match({
            group: (_$2, p) => East.str`${p.name}: ${p.tasks.map((_$3, t) => t.task).stringJoin(" → ")}`,
            row:   (_$2, t) => t.task,
        }));
    })

